export function OptimisticState({
  itemLabel = "{{itemLabel}}",
  stage = "{{stage}}",
  accent = "{{accent}}",
  baseLikes = {{baseLikes}},
}) {
  const count = stage === "rolled-back" ? baseLikes : `${baseLikes} + 1`;
  const notes = {
    optimistic: "UI updated instantly, before the server replied.",
    confirmed: "Server confirmed \u2014 optimistic value was correct.",
    "rolled-back": "Server rejected the like \u2014 UI rolled back to the real count.",
  };
  return (
    <div role="status" style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontWeight: 700 }}>{itemLabel}</p>
      <div style={{ padding: 12, borderRadius: 8, background: "#24143010", textAlign: "center", fontSize: 20, fontWeight: 800, marginBottom: 10, color: stage !== "rolled-back" ? accent : "#241430" }}>&#9829; {count}</div>
      <p style={{ margin: 0, fontSize: 11, color: "#24143099" }}>{notes[stage]}</p>
    </div>
  );
}
